with expected as(select $warnings${"pl":"Zamkni\u0119cie dla zwyk\u0142ej turystyki pieszej: 1 listopada 2026 \u2013 31 maja 2027. Obejmuje wej\u015bcie z Tri studni\u010dky oraz odcinek od Jamsk\u00e9ho plesa na Krywa\u0144. Plik GPX nie oznacza, \u017ce szlak jest otwarty. Przed wyj\u015bciem sprawd\u017a aktualny komunikat TANAP.","en":"Closed to ordinary hiking from 1 November 2026 to 31 May 2027, including the Tri studni\u010dky ascent and the section from Jamsk\u00e9 pleso to Kriv\u00e1\u0148. A GPX file does not confirm access. Check the latest TANAP notice before setting off.","ua":"\u0417\u0430\u043a\u0440\u0438\u0442\u043e \u0434\u043b\u044f \u0437\u0432\u0438\u0447\u0430\u0439\u043d\u0438\u0445 \u043f\u0456\u0448\u0438\u0445 \u043f\u043e\u0445\u043e\u0434\u0456\u0432 \u0432\u0456\u0434 1 \u043b\u0438\u0441\u0442\u043e\u043f\u0430\u0434\u0430 2026 \u0434\u043e 31 \u0442\u0440\u0430\u0432\u043d\u044f 2027, \u0437\u043e\u043a\u0440\u0435\u043c\u0430 \u043f\u0456\u0434\u0439\u043e\u043c \u0456\u0437 Tri studni\u010dky \u0442\u0430 \u0432\u0456\u0434\u0440\u0456\u0437\u043e\u043a \u0432\u0456\u0434 Jamsk\u00e9 pleso \u043d\u0430 Kriv\u00e1\u0148. \u041d\u0430\u044f\u0432\u043d\u0456\u0441\u0442\u044c GPX \u043d\u0435 \u043e\u0437\u043d\u0430\u0447\u0430\u0454, \u0449\u043e \u0441\u0442\u0435\u0436\u043a\u0430 \u0432\u0456\u0434\u043a\u0440\u0438\u0442\u0430. \u041f\u0435\u0440\u0435\u0434 \u0432\u0438\u0445\u043e\u0434\u043e\u043c \u043f\u0435\u0440\u0435\u0432\u0456\u0440\u0442\u0435 \u0430\u043a\u0442\u0443\u0430\u043b\u044c\u043d\u0435 \u043f\u043e\u0432\u0456\u0434\u043e\u043c\u043b\u0435\u043d\u043d\u044f TANAP.","zh":"\u666e\u901a\u5f92\u6b65\u5b63\u8282\u6027\u5c01\u95ed\uff1a2026\u5e7411\u67081\u65e5\u81f32027\u5e745\u670831\u65e5\uff0c\u5305\u62ec\u4eceTri studni\u010dky\u4e0a\u5c71\u53ca\u4eceJamsk\u00e9 pleso\u524d\u5f80Kriv\u00e1\u0148\u7684\u8def\u6bb5\u3002\u63d0\u4f9bGPX\u6587\u4ef6\u5e76\u4e0d\u4ee3\u8868\u8def\u7ebf\u5f00\u653e\u3002\u51fa\u53d1\u524d\u8bf7\u67e5\u770bTANAP\u6700\u65b0\u516c\u544a\u3002"}$warnings$::jsonb texts)
select a.id access_id,a.trail_id,i.lang,i.warnings,
 i.warnings=expected.texts->>i.lang warning_matches_review,a.source_url,a.last_verified_at,
 exists(select from peakguide_private.catalogue_batch_receipts where batch_key='krivan-seasonal-01') patch_applied
from public.trail_access a join public.trail_access_i18n i on i.access_id=a.id cross join expected
where a.trail_id=10 order by i.lang collate "C";
